package com.gymmind.nutrition.domain.model;
import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="nutrition_record") public class NutritionRecord extends TenantScopedEntity { @Column(name="member_id",nullable=false) Long memberId; @Column(name="record_date",nullable=false) LocalDate recordDate; @Column(nullable=false) double calories; @Column(nullable=false) double protein; @Column(nullable=false) double carbohydrate; @Column(nullable=false) double fat; @Column(nullable=false,length=2000) String notes; protected NutritionRecord(){} private NutritionRecord(Long t,Long m,LocalDate d,double c,double p,double carb,double f,String n){super(t);if(m==null||m<=0||d==null||c<0||p<0||carb<0||f<0||n==null||n.isBlank())throw new IllegalArgumentException("Invalid nutrition record");memberId=m;recordDate=d;calories=c;protein=p;carbohydrate=carb;fat=f;notes=n.trim();} public static NutritionRecord create(Long t,Long m,LocalDate d,double c,double p,double carb,double f,String n){return new NutritionRecord(t,m,d,c,p,carb,f,n);} public Long getMemberId(){return memberId;} public LocalDate getRecordDate(){return recordDate;} public double getCalories(){return calories;} public double getProtein(){return protein;} public double getCarbohydrate(){return carbohydrate;} public double getFat(){return fat;} public String getNotes(){return notes;} }
